import {esc,fmt} from './ui.js';
export function extraToolsHTML(){return `<section class="panel glass"><div class="panel-head"><h2>Isotopes & weighted means</h2><span class="badge">1.17</span></div><div class="panel-body"><form id="isotope-form" class="tool-form"><div class="row"><div class="field"><label for="iso-a">First isotope mass</label><input id="iso-a" type="number" min="1" value="35" step="any" required></div><div class="field"><label for="iso-b">Second isotope mass</label><input id="iso-b" type="number" min="1" value="37" step="any" required></div></div><div class="field"><label for="iso-abundance">Abundance of first isotope / %</label><input id="iso-abundance" type="number" min="0" max="100" value="75" step="any" required></div><button class="btn primary">Calculate relative atomic mass</button></form><div id="isotope-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Find an unknown concentration</h2><span class="badge">Titration</span></div><div class="panel-body"><form id="titre-form" class="tool-form"><div class="field"><label for="titre-equation">Reaction</label><select id="titre-equation"><option value="1">HCl + NaOH → NaCl + H₂O</option><option value="2">H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O</option></select></div><div class="field"><label for="titre-acid">Unknown acid volume / cm³</label><input id="titre-acid" type="number" min="0.001" value="25" step="any" required></div><div class="row"><div class="field"><label for="titre-base">NaOH titre / cm³</label><input id="titre-base" type="number" min="0.001" value="20" step="any" required></div><div class="field"><label for="titre-conc">NaOH / mol dm⁻³</label><input id="titre-conc" type="number" min="0.001" value="0.1" step="any" required></div></div><button class="btn primary">Show mole-ratio working</button></form><div id="titre-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Make sense of repeat results</h2></div><div class="panel-body"><form id="repeat-form" class="tool-form"><div class="field"><label for="repeat-values">Values separated by commas</label><input id="repeat-values" value="24.8, 24.9, 24.8" maxlength="1000" required></div><button class="btn primary">Calculate mean & spread</button></form><p class="tools-help">Select appropriate concordant results yourself; the tool does not discard anomalies automatically. Half-range gives one simple estimate of spread.</p><div id="repeat-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Bonding, one electron at a time</h2></div><div class="panel-body"><div class="field"><label for="bonding-type">Structure to inspect</label><select id="bonding-type"><option>H₂ · single covalent bond</option><option>O₂ · double covalent bond</option><option>N₂ · triple covalent bond</option><option>NaCl · ionic electron transfer</option><option>MgO · ionic electron transfer</option></select></div><div id="bonding-diagram" style="margin-top:18px"></div><p class="tools-help">Dots and crosses distinguish the atoms’ original electrons; electrons are physically identical. Only outer electrons are shown.</p></div></section>`;}
export function mountExtraTools(container){
 const find=s=>container.querySelector(s);
 const result=(id,fn)=>{try{find(id).innerHTML=`<div class="result">${fn()}</div>`;}catch(e){find(id).innerHTML=`<div class="result error">${esc(e.message)}</div>`;}};
 find('#isotope-form').onsubmit=e=>{e.preventDefault();result('#isotope-result',()=>{const a=Number(find('#iso-a').value),b=Number(find('#iso-b').value),p=Number(find('#iso-abundance').value);if(![a,b,p].every(Number.isFinite)||a<=0||b<=0||p<0||p>100)throw Error('Use positive isotope masses and an abundance from 0 to 100%.');return `Ar = (${a} × ${p} + ${b} × ${100-p}) ÷ 100<br><b>${fmt((a*p+b*(100-p))/100,4)}</b> (relative value, no unit)`;});};
 find('#titre-form').onsubmit=e=>{e.preventDefault();result('#titre-result',()=>{const a=Number(find('#titre-acid').value),b=Number(find('#titre-base').value),c=Number(find('#titre-conc').value),ratio=Number(find('#titre-equation').value);if(![a,b,c,ratio].every(v=>Number.isFinite(v)&&v>0))throw Error('All quantities must be positive.');const n=b/1000*c,na=n/ratio;return `n(NaOH) = ${c} × ${b}/1000 = ${fmt(n,6)} mol<br>n(acid) = ${fmt(n,6)} ÷ ${ratio} = ${fmt(na,6)} mol<br>c(acid) = ${fmt(na,6)} ÷ (${a}/1000)<br><b>${fmt(na/(a/1000),5)} mol/dm³</b>`;});};
 find('#repeat-form').onsubmit=e=>{e.preventDefault();result('#repeat-result',()=>{const tokens=find('#repeat-values').value.split(',').map(x=>x.trim());if(tokens.some(s=>s==='')||tokens.length<2||tokens.length>100)throw Error('Enter 2–100 values separated by commas.');const a=tokens.map(Number);if(!a.every(Number.isFinite))throw Error('Every value must be a finite number.');const mean=a.reduce((s,v)=>s+v,0)/a.length,spread=Math.max(...a)-Math.min(...a);return `Mean = <b>${fmt(mean,5)}</b><br>Range = ${fmt(spread,5)} · half-range = ±${fmt(spread/2,5)}<br>${mean===0?'Percentage spread is undefined for a zero mean.':'Half-range as % of mean = '+fmt(Math.abs(spread/2/mean*100),3)+'%'}<p class="hint">Repeated values do not reveal a systematic calibration error.</p>`;});};
 function diagram(){const i=Number(find('#bonding-type').value)||find('#bonding-type').selectedIndex||0,ionic=i>=3;
  let art='',explanation='';
  if(!ionic){const pairs=i+1,symbol=['H','O','N'][i],outer=[1,6,5][i],lone=(outer-pairs)/2;art=`<text x="125" y="87" text-anchor="middle" font-size="30" fill="#759bc9">${symbol}</text><text x="235" y="87" text-anchor="middle" font-size="30" fill="#91a7ba">${symbol}</text>${Array.from({length:pairs},(_,j)=>`<text x="171" y="${68+j*18}" font-size="17" fill="#638fce">•</text><text x="186" y="${68+j*18}" font-size="13" fill="#b286b9">×</text>`).join('')}${Array.from({length:lone},(_,j)=>{const x=j===0?112:j===1?80:112,y=j===0?40:j===1?85:120;return `<text x="${x}" y="${y}" fill="#638fce" font-size="15">••</text><text x="${360-x-20}" y="${y}" fill="#b286b9" font-size="13">××</text>`;}).join('')}`;explanation=`${pairs} shared electron ${pairs===1?'pair':'pairs'}; ${lone} lone ${lone===1?'pair':'pairs'} on each atom. Each shared pair is a covalent bond.`;}
  else{const metal=i===3?'Na':'Mg',non=i===3?'Cl':'O',q=i===3?1:2;art=`<text x="105" y="88" font-size="28" fill="#759bc9">[${metal}]</text><text x="155" y="65" font-size="14" fill="#759bc9">${q===1?'+':'2+'}</text><text x="228" y="88" text-anchor="middle" font-size="30" fill="#91a7ba">${non}</text><path d="M192 30h-6v104h6M263 30h6v104h-6" fill="none" stroke="#829ebc"/><text x="274" y="35" font-size="14" fill="#91a7ba">${q===1?'−':'2−'}</text>${Array.from({length:8},(_,j)=>{const ang=j*Math.PI/4,x=228+Math.cos(ang)*29,y=80+Math.sin(ang)*34;return `<text x="${x-4}" y="${y+4}" font-size="${j<q?13:16}" fill="${j<q?'#638fce':'#b286b9'}">${j<q?'•':'×'}</text>`;}).join('')}`;explanation=`${metal} transfers ${q} electron${q===1?'':'s'} to ${non}. The non-metal outer shell and the transferred electrons are shown; the metal’s filled inner shells are omitted. Electrostatic attraction acts throughout the giant ionic lattice; these are not separate molecules.`;}
  find('#bonding-diagram').innerHTML=`<svg viewBox="0 0 360 150" role="img" aria-label="${esc(explanation)}" style="width:100%;height:160px">${art}</svg><div class="callout">${esc(explanation)}</div>`;
 }
 find('#bonding-type').onchange=diagram;diagram();
}
